 (ROOT/'docs/fixed-deployment-profile-certification.md').write_text(output+'\n')
 # Only passing references may be added to deployment documentation.
 deployment=ROOT/'docs/deployment.md';s=deployment.read_text();marker='## Certified Ankara reference deployments'
 if minimum and marker not in s:
  block=f"## Certified Ankara reference deployments\n\nCertification dated **2026-10-05**, A.T.O.M **{r['source_version']}**, names Profile **{minimum}** as the minimum certified reference"
